1342	function Sparkline({ history }: { history: RubricHistoryEntry[] }) {
1343	  const points = sparklinePoints(history);
1344	  if (points.length < 2) return null;
1345	  const w = 100;
1346	  const h = 24;
1347	  const path = points
1348	    .map(
1349	      (p, i) =>
1350	        `${i === 0 ? "M" : "L"} ${(p.x * w).toFixed(1)} ${((1 - p.y) * h).toFixed(1)}`,
1351	    )
1352	    .join(" ");
1353	  const last = points[points.length - 1];
1354	  const first = history[0];
1355	  const latest = history[history.length - 1];
1356	
1357	  return (
1358	    <div class="mt-1.5">
1359	      <svg
1360	        viewBox={`0 0 ${w} ${h}`}
1361	        width="100%"
1362	        height="28"
1363	        preserveAspectRatio="none"
1364	        role="img"
1365	        aria-label={`Grade over ${history.length} passes, from ${first.overall} to ${latest.overall} out of 100`}
1366	      >
1367	        <path
1368	          d={path}
1369	          fill="none"
1370	          stroke="var(--color-vermilion-2)"
1371	          stroke-width="1.5"
1372	          vector-effect="non-scaling-stroke"
1373	          stroke-linejoin="round"
1374	        />
1375	        <circle
1376	          cx={last.x * w}
1377	          cy={(1 - last.y) * h}
1378	          r="2"
1379	          fill="var(--color-vermilion)"
1380	          vector-effect="non-scaling-stroke"
1381	        />
1382	      </svg>
1383	      <p
1384	        class="mt-0.5 text-[10px] tracking-[0.1em] text-[var(--color-ink-muted)]"
1385	        style="font-family: var(--font-typewriter);"
1386	      >
1387	        {history.length} passes · {first.overall} → {latest.overall}
1388	      </p>
1389	    </div>
1390	  );
1391	}
